  function hmDecodeCss(encoded) {
    var bytes = atob(encoded);
    var data = new Uint8Array(bytes.length);
    for (var i = 0; i < bytes.length; i++) data[i] = bytes.charCodeAt(i);
    return new TextDecoder('utf-8').decode(data);
  }


